{
  "title": "长安城的隐秘",
  "scene": "期末考试前夜，小林在长安城的巷弄里穿梭，寻找隐藏的复习资料。他突然发现，机器猫正悄悄跟踪一名穿着古装的路人，似乎在寻找什么。小林心想，是否应该借此机会接近，还是先完成期末复习？又或者，直接去长安城藏书阁查看资料？",
  "goal": "找到复习资料并避开监控，顺利通过期末考试。",
  "clue": "机器猫跟踪的人穿着古装，古装人物位于长安城，隐秘的复习资料在藏书阁。",
  "choices": [
    {"id": "A", "text": "跟踪机器猫", "outcome": "小林成功接近了跟踪对象，发现一盒复习资料，但被巡逻士兵发现了，复习资料被没收。", "result": "partial", "next": "retry"},
    {"id": "B", "text": "直接去藏书阁", "outcome": "小林顺利找到了复习资料，并在里面发现了一把会说话的剑，但被藏书阁的守卫怀疑是非法访问，限制了小林的复习时间。", "result": "success", "next": "next_level"},
    {"id": "C", "text": "与古装人交谈", "outcome": "小林尝试与古装人交谈，但对方不理睬，只顾着四处张望，似乎在寻找什么东西。小林错过了一次接近机器猫的机会。", "result": "fail", "next": "retry"}
  ]
}
